import csv
import io
import re
import collections


_EXPECTED_WIDTH = 9
_PAIR_RE = re.compile(
    r'"((?:\\.|[^"\\])*)"\s*:\s*"((?:\\.|[^"\\])*)"'
)
_URI_RE = re.compile(r"^[A-Za-z][A-Za-z0-9+.-]*://")


def _fallback_reader(text):
    rows = []
    row = []
    field = []
    quoted = False
    field_started = False
    i = 0
    length = len(text)

    while i < length:
        ch = text[i]

        if quoted:
            if ch == '"':
                if i + 1 < length and text[i + 1] == '"':
                    field.append('"')
                    i += 2
                    continue
                quoted = False
            else:
                field.append(ch)
            i += 1
            continue

        if ch == '"' and not field_started:
            quoted = True
            field_started = True
            i += 1
            continue

        if ch == ",":
            row.append("".join(field))
            field = []
            field_started = False
            i += 1
            continue

        if ch == "\r" or ch == "\n":
            row.append("".join(field))
            rows.append(row)
            row = []
            field = []
            field_started = False
            if ch == "\r" and i + 1 < length and text[i + 1] == "\n":
                i += 2
            else:
                i += 1
            continue

        field.append(ch)
        field_started = True
        i += 1

    if field_started or field or row:
        row.append("".join(field))
        rows.append(row)

    return rows


def _read_records(text):
    try:
        current_limit = csv.field_size_limit()
        desired_limit = max(current_limit, len(text) + 1)
        try:
            csv.field_size_limit(desired_limit)
        except (OverflowError, ValueError):
            pass
        return [
            list(record)
            for record in csv.reader(
                io.StringIO(text, newline=""),
                delimiter=",",
                quotechar='"',
                doublequote=True,
                strict=False,
            )
        ]
    except (csv.Error, UnicodeError):
        return _fallback_reader(text)


def _header_score(record):
    if not record:
        return -1

    nonempty = sum(bool(value.strip()) for value in record)
    normalized = [value.strip().casefold() for value in record if value.strip()]
    unique = len(set(normalized))
    label_like = 0
    reasonable = 0

    for value in record:
        stripped = value.strip()
        if re.fullmatch(r"[A-Za-z_][A-Za-z0-9_ ./()#%+-]*", stripped or ""):
            label_like += 1
        if stripped and len(stripped) <= 80 and "\n" not in stripped and "\r" not in stripped:
            reasonable += 1

    return nonempty * 4 + unique * 3 + label_like * 5 + reasonable


def _find_header_index(records):
    if not records:
        return None

    exact = [
        index
        for index, record in enumerate(records[:50])
        if len(record) == _EXPECTED_WIDTH
    ]

    if exact:
        return max(exact, key=lambda index: (_header_score(records[index]), -index))

    nonempty = [
        index
        for index, record in enumerate(records[:50])
        if record
    ]
    if not nonempty:
        return 0

    maximum_width = max(len(records[index]) for index in nonempty)
    candidates = [
        index for index in nonempty
        if len(records[index]) == maximum_width
    ]
    return max(candidates, key=lambda index: (_header_score(records[index]), -index))


def _decode_escaped_string(value):
    result = []
    i = 0
    simple = {
        '"': '"',
        "\\": "\\",
        "/": "/",
        "b": "\b",
        "f": "\f",
        "n": "\n",
        "r": "\r",
        "t": "\t",
    }

    while i < len(value):
        if value[i] != "\\" or i + 1 >= len(value):
            result.append(value[i])
            i += 1
            continue

        marker = value[i + 1]
        if marker in simple:
            result.append(simple[marker])
            i += 2
            continue

        if marker == "u" and i + 5 < len(value):
            digits = value[i + 2:i + 6]
            if re.fullmatch(r"[0-9A-Fa-f]{4}", digits):
                result.append(chr(int(digits, 16)))
                i += 6
                continue

        result.append(marker)
        i += 2

    return "".join(result)


def _parse_string_object(value):
    stripped = value.strip()
    if len(stripped) < 2 or stripped[0] != "{" or stripped[-1] != "}":
        return None

    inner = stripped[1:-1]
    matches = list(_PAIR_RE.finditer(inner))
    if not matches:
        return None

    remainder = _PAIR_RE.sub("", inner)
    if not re.fullmatch(r"[\s,]*", remainder):
        return None

    pairs = []
    for match in matches:
        pairs.append((
            _decode_escaped_string(match.group(1)),
            _decode_escaped_string(match.group(2)),
        ))
    return pairs


def _normalize_name(value):
    return re.sub(r"[^0-9a-z]+", "", value.casefold())


def _expand_embedded_object(row, columns):
    width = len(columns)
    name_positions = collections.defaultdict(list)

    for index, name in enumerate(columns):
        normalized = _normalize_name(name)
        if normalized:
            name_positions[normalized].append(index)

    for object_index, value in enumerate(row):
        pairs = _parse_string_object(value)
        if not pairs or len(pairs) < 2:
            continue

        mapped = []
        seen = set()
        valid = True

        for key, object_value in pairs:
            positions = name_positions.get(_normalize_name(key), [])
            if len(positions) != 1 or positions[0] in seen:
                valid = False
                break
            seen.add(positions[0])
            mapped.append((positions[0], object_value))

        if not valid:
            continue

        expanded_size = len(row) - 1 + len(mapped)
        if abs(expanded_size - width) >= abs(len(row) - width):
            continue

        sentinel = object()
        result = [sentinel] * width

        if object_index > width:
            continue

        for index, item in enumerate(row[:object_index]):
            if index >= width:
                valid = False
                break
            result[index] = item

        if not valid:
            continue

        for index, object_value in mapped:
            if result[index] is not sentinel:
                valid = False
                break
            result[index] = object_value

        if not valid:
            continue

        tail = row[object_index + 1:]
        available = [
            index for index in range(object_index, width)
            if result[index] is sentinel
        ]

        if len(tail) > len(available):
            continue

        for index, item in zip(available, tail):
            result[index] = item

        return ["" if item is sentinel else item for item in result]

    return row


def _modal_uri_column(rows, width):
    counts = collections.Counter()

    for row in rows:
        if len(row) != width:
            continue
        for index, value in enumerate(row):
            if _URI_RE.match(value.strip()):
                counts[index] += 1

    if not counts:
        return None
    return counts.most_common(1)[0][0]


def _fit_width(row, width, uri_column):
    if len(row) == width:
        return list(row)

    if len(row) < width:
        return list(row) + [""] * (width - len(row))

    if uri_column is not None:
        uri_positions = [
            index for index, value in enumerate(row)
            if _URI_RE.match(value.strip())
        ]
        if uri_positions:
            source_uri = min(
                uri_positions,
                key=lambda index: abs(index - uri_column)
            )
            prefix = list(row[:source_uri])
            suffix = list(row[source_uri:])

            if len(prefix) > uri_column:
                if uri_column > 0:
                    prefix = (
                        prefix[:uri_column - 1]
                        + [",".join(prefix[uri_column - 1:])]
                    )
                else:
                    prefix = []
            elif len(prefix) < uri_column:
                prefix += [""] * (uri_column - len(prefix))

            required_suffix = width - uri_column
            if len(suffix) > required_suffix:
                if required_suffix > 0:
                    suffix = (
                        suffix[:required_suffix - 1]
                        + [",".join(suffix[required_suffix - 1:])]
                    )
                else:
                    suffix = []
            elif len(suffix) < required_suffix:
                suffix += [""] * (required_suffix - len(suffix))

            fitted = prefix + suffix
            if len(fitted) == width:
                return fitted

    if width <= 0:
        return []

    return list(row[:width - 1]) + [",".join(row[width - 1:])]


def parse_csv(raw_csv: str):
    if not isinstance(raw_csv, str):
        raw_csv = str(raw_csv)

    records = _read_records(raw_csv)
    if not records:
        return {"columns": [], "rows": []}

    if records[0]:
        records[0][0] = records[0][0].lstrip("\ufeff")

    header_index = _find_header_index(records)
    if header_index is None:
        return {"columns": [], "rows": []}

    columns = [str(value) for value in records[header_index]]
    width = len(columns)

    if width == 0:
        return {"columns": [], "rows": []}

    preliminary_rows = []
    for record in records[header_index + 1:]:
        row = [str(value) for value in record]
        preliminary_rows.append(_expand_embedded_object(row, columns))

    uri_column = _modal_uri_column(preliminary_rows, width)
    rows = [
        _fit_width(row, width, uri_column)
        for row in preliminary_rows
    ]

    return {"columns": columns, "rows": rows}
